import java.io.*;import java.util.*;class Result {static class Edge {int to, cost;Edge(int to, int cost) {this.to = to;this.cost = cost;}}public static int beautifulPath(List<List<Integer>> edgesInput, int A, int B) {int maxNode = 0;for (List<Integer> edge : edgesInput) {maxNode = Math.max(maxNode, Math.max(edge.get(0), edge.get(1)));}maxNode = Math.max(maxNode, Math.max(A, B));List<List<Edge>> adj = new ArrayList<>(maxNode + 1);for (int i = 0; i <= maxNode; i++) adj.add(new ArrayList<>());for (List<Integer> edge : edgesInput) {adj.get(edge.get(0)).add(new Edge(edge.get(1), edge.get(2)));adj.get(edge.get(1)).add(new Edge(edge.get(0), edge.get(2)));}boolean[][] visited = new boolean[maxNode + 1][1024];Queue<int[]> q = new LinkedList<>();q.add(new int[]{A, 0});visited[A][0] = true;int minPenalty = -1;while (!q.isEmpty()) {int[] curr = q.poll();int u = curr[0];int p = curr[1];if (u == B) {if (minPenalty == -1 || p < minPenalty) {minPenalty = p;}}for (Edge e : adj.get(u)) {int nextP = p | e.cost;if (!visited[e.to][nextP]) {visited[e.to][nextP] = true;q.add(new int[]{e.to, nextP});}}}return minPenalty;}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line1 = br.readLine();if (line1 == null) return;String[] parts1 = line1.split(" ");int n = Integer.parseInt(parts1[0]);int m = Integer.parseInt(parts1[1]);List<List<Integer>> edges = new ArrayList<>();for (int i = 0; i < m; i++) {String edgeLine = br.readLine();if (edgeLine == null) break;String[] edgeParts = edgeLine.split(" ");List<Integer> edge = new ArrayList<>();edge.add(Integer.parseInt(edgeParts[0]));edge.add(Integer.parseInt(edgeParts[1]));edge.add(Integer.parseInt(edgeParts[2]));edges.add(edge);}String lineLast = br.readLine();if (lineLast == null) return;String[] lastParts = lineLast.split(" ");int A = Integer.parseInt(lastParts[0]);int B = Integer.parseInt(lastParts[1]);System.out.println(Result.beautifulPath(edges, A, B));}}